def get_max_sum(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Calculate the sum of the maximum values for n/2, n/3, n/4, and n/5
    if n % 2 == 0:
        half = get_max_sum(n // 2, memo)
    else:
        half = 0

    if n % 3 == 0:
        third = get_max_sum(n // 3, memo)
    else:
        third = 0

    if n % 4 == 0:
        fourth = get_max_sum(n // 4, memo)
    else:
        fourth = 0

    if n % 5 == 0:
        fifth = get_max_sum(n // 5, memo)
    else:
        fifth = 0

    max_sum = max(half + third + fourth + fifth, n)

    memo[n] = max_sum
    return max_sum

